/// <summary>
/// PaffH 30.04.21
/// build searchname from productnumber instead of productname
/// </summary>
/// <param name = "_productCreationData">EcoResIProductCrossTableData</param>
public static void defaultProductSearchName(EcoResIProductCrossTableData _productCreationData)
{

    EcoResProductNumber productNumber = _productCreationData.productData().identification().parmProductNumber();
    productNumber = NDXItemIdHandler::constructFromDataAreaId().checkSearchName(productNumber);
    EcoResProductSearchName productSearchName = name2Alias(productNumber);
    _productCreationData.productData().identification().parmProductSearchName(productSearchName);

    next defaultProductSearchName(_productCreationData);
}

/// <summary>
/// PaffH 26.05.21
/// check itemId (from productNumber)
/// </summary>
/// <param name = "_productCreationData">EcoResIProductCrossTableData</param>
public static void defaultItemId(EcoResIProductCrossTableData _productCreationData)
{
    if (_productCreationData.productData().identification().isReleasedProduct() && !_productCreationData.productData().identification().companySpecificData().parmItemId())
    {
        EcoResProductNumber productNumber = _productCreationData.productData().identification().parmProductNumber();
        productNumber = NDXItemIdHandler::constructFromDataAreaId().checkItemId(productNumber, "@NDX:NDXCheckItemIdAttachedMessage1");
        _productCreationData.productData().identification().companySpecificData().parmItemId(productNumber);
    }
    next defaultItemId(_productCreationData);
}

/// <summary>
/// PaffH 27.05.21
/// save searchName form product to released product
/// </summary>
/// <param name = "_productCreationData">EcoResIProductCrossTableData</param>
public static void defaultSearchName(EcoResIProductCrossTableData _productCreationData)
{
    _productCreationData.productData().identification().companySpecificData().parmSearchName(_productCreationData.productData().identification().parmProductSearchName());

    next defaultSearchName(_productCreationData);
}
